import { types } from "node:util";
/** Inspect only plain own data; original runtime identities are never reconstructed from this copy. */
export function snapshotPlainData(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
  errorCode = "plain_data_invalid",
): unknown {
  if (
    value === null ||
    ["string", "boolean"].includes(typeof value) ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (!value || typeof value !== "object" || types.isProxy(value) || depth > 16 || seen.has(value))
    throw new Error(errorCode);
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value);
  if (prototype !== (array ? Array.prototype : Object.prototype) && prototype !== null)
    throw new Error(errorCode);
  seen.add(value);
  try {
    const descriptors = Object.getOwnPropertyDescriptors(value),
      result: Record<string, unknown> = {};
    if (Reflect.ownKeys(descriptors).some((key) => typeof key !== "string"))
      throw new Error(errorCode);
    for (const [key, d] of Object.entries(descriptors)) {
      if (array && key === "length") continue;
      if (!("value" in d) || !d.enumerable) throw new Error(errorCode);
      Object.defineProperty(result, key, {
        enumerable: true,
        value: snapshotPlainData(d.value, seen, depth + 1, arrayLimit, errorCode),
      });
    }
    if (!array) return result;
    const length = descriptors.length?.value;
    if (
      !Number.isSafeInteger(length) ||
      length < 0 ||
      length > arrayLimit ||
      Object.keys(result).length !== length ||
      !Array.from({ length }, (_, i) => Object.hasOwn(result, i)).every(Boolean)
    )
      throw new Error(errorCode);
    return Array.from({ length }, (_, i) => result[i]);
  } finally {
    seen.delete(value);
  }
}

/** Stable per-game streams. Forking depends on names, never on parent consumption. */
export const RANDOM_ALGORITHM = "mulberry32-fnv1a-utf16-v1" as const;
export const RANDOM_STREAM_POLICY = "named-path-v1" as const;

export interface RandomMetadata {
  seed: string;
  algorithm: typeof RANDOM_ALGORITHM;
  streamPolicy: typeof RANDOM_STREAM_POLICY;
  path: readonly string[];
}

export interface RandomSource {
  readonly metadata: RandomMetadata;
  next(): number;
  fork(name: string): RandomSource;
}

/** Decision capability: no seed, path, or ability to derive other streams. */
export interface RandomDraws {
  next(): number;
}

export function randomDraws(source: RandomSource): RandomDraws {
  return Object.freeze({ next: () => source.next() });
}

class SeededRandom implements RandomSource {
  readonly metadata: RandomMetadata;
  private state: number;

  constructor(seed: string, path: readonly string[] = []) {
    if (!seed.trim()) throw new Error("random_seed_empty");
    this.metadata = Object.freeze({
      seed,
      algorithm: RANDOM_ALGORITHM,
      streamPolicy: RANDOM_STREAM_POLICY,
      path: Object.freeze([...path]),
    });
    const input = JSON.stringify([seed, ...path]);
    let hash = 0x811c9dc5;
    for (let index = 0; index < input.length; index++)
      hash = Math.imul(hash ^ input.charCodeAt(index), 0x01000193) >>> 0;
    this.state = hash;
  }

  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let value = this.state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 0x100000000;
  }

  fork(name: string): RandomSource {
    if (!name.trim()) throw new Error("random_stream_name_empty");
    return new SeededRandom(this.metadata.seed, [...this.metadata.path, name]);
  }
}

export function createRandom(seed: string = crypto.randomUUID()): RandomSource {
  return new SeededRandom(seed);
}

export function shuffled<T>(values: readonly T[], random: RandomSource): T[] {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index--) {
    const target = Math.floor(random.next() * (index + 1));
    [result[index], result[target]] = [result[target], result[index]];
  }
  return result;
}

import { types } from "node:util";
import { z } from "zod";

const positive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const stepSchema = z.strictObject({
  id: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/),
  at: z.strictObject({
    day: positive.min(2),
    point: z.literal("before_night_source_freeze"),
    afterDecision: z.strictObject({
      actorId: positive,
      stage: z.literal("demon_hunter"),
      turn: z.literal(1),
    }),
  }),
  mutation: z.strictObject({
    kind: z.literal("replace_alive_component"),
    playerId: positive,
    alive: z.literal(true),
  }),
});
const faultPlanSchema = z
  .strictObject({
    version: z.literal("awa_fault_plan_v1"),
    steps: z.array(stepSchema).min(1).max(16),
  })
  .refine(
    (plan) =>
      new Set(plan.steps.map((step) => step.id)).size === plan.steps.length &&
      plan.steps.every((step, index) => index === 0 || step.at.day > plan.steps[index - 1]!.at.day),
    "fault_plan_order_invalid",
  );
export type FaultPlan = z.infer<typeof faultPlanSchema>;
export type FaultStep = FaultPlan["steps"][number];

/** Read data descriptors only; an offline fault input must never execute user code. */
export function readFaultPlanData(value: unknown, seen = new Set<object>(), depth = 0): unknown {
  if (value === null || ["string", "number", "boolean"].includes(typeof value)) return value;
  if (!value || typeof value !== "object" || types.isProxy(value) || depth > 12 || seen.has(value))
    throw new Error("fault_plan_input_invalid");
  seen.add(value);
  try {
    const array = Array.isArray(value),
      prototype = Object.getPrototypeOf(value);
    if (prototype !== (array ? Array.prototype : Object.prototype) && prototype !== null)
      throw new Error("fault_plan_input_invalid");
    const descriptors = Object.getOwnPropertyDescriptors(value);
    if (Reflect.ownKeys(descriptors).some((key) => typeof key !== "string"))
      throw new Error("fault_plan_input_invalid");
    const result: Record<string, unknown> = {};
    for (const [key, descriptor] of Object.entries(descriptors)) {
      if (array && key === "length") continue;
      if (key === "__proto__" || !("value" in descriptor) || !descriptor.enumerable)
        throw new Error("fault_plan_input_invalid");
      result[key] = readFaultPlanData(descriptor.value, seen, depth + 1);
    }
    if (!array) return result;
    const length = descriptors.length?.value;
    if (
      !Number.isSafeInteger(length) ||
      length < 0 ||
      length > 64 ||
      Object.keys(result).length !== length ||
      Object.keys(result).some((key) => !/^(0|[1-9][0-9]*)$/.test(key) || Number(key) >= length)
    )
      throw new Error("fault_plan_input_invalid");
    return Array.from({ length }, (_, index) => result[index]);
  } finally {
    seen.delete(value);
  }
}
function deepFreeze<T>(value: T): T {
  if (value && typeof value === "object") {
    for (const item of Object.values(value)) deepFreeze(item);
    Object.freeze(value);
  }
  return value;
}
export function readFaultPlan(value: unknown): FaultPlan {
  return deepFreeze(faultPlanSchema.parse(readFaultPlanData(value)));
}

import { EntityId } from "../model";

/**
 * 玩家身份组件：记录实体 ID、座位号、显示名与会话 ID。
 */
export interface IdentityComponent {
  id: EntityId;
  seat: number;
  name: string;
  sessionId: string;
}

/**
 * 创建玩家身份组件。
 */
export function createIdentityComponent(
  id: EntityId,
  seat: number,
  name: string,
): IdentityComponent {
  return {
    id,
    seat,
    name,
    // 会话 ID 目前采用稳定前缀 + 实体 ID，便于日志排查。
    sessionId: `player_${id}`,
  };
}

import { Phase } from "../model";

/**
 * 阶段顺序注册表：支持按板子动态替换默认 phase 顺序。
 */
export class PhaseRegistry {
  private order: Phase[];

  constructor(order: Phase[] = [Phase.Night, Phase.Day, Phase.Voting]) {
    this.order = [...order];
  }

  /**
   * 获取当前阶段顺序配置。
   */
  getOrder(): Phase[] {
    return [...this.order];
  }

  /**
   * 注册新的阶段顺序配置。
   */
  registerOrder(order: Phase[]): void {
    this.order = [...order];
  }
}

import { Role, ToolName } from "../model";

/**
 * 角色工具注册表：
 * 负责“角色 -> 可调用工具列表”的集中管理。
 */
export class RoleRegistry {
  private readonly toolMap: Map<Role, ToolName[]> = new Map();

  constructor() {
    for (const role of Object.values(Role)) {
      this.toolMap.set(role, []);
    }
  }

  /**
   * 获取角色当前可调用工具列表。
   */
  getAllowedTools(role: Role): ToolName[] {
    return [...(this.toolMap.get(role) ?? [])];
  }

  /**
   * 覆盖注册角色可调用工具列表。
   */
  registerAllowedTools(role: Role, tools: ToolName[]): void {
    this.toolMap.set(role, [...tools]);
  }
}

