/**
 * 负责在声明的决策与来源冻结边界执行显式夜间故障计划。输入为计划描述与当前 World 引用；
 * 输出保留实际故障及计划消费检查。这个受控故障驱动不创造正常角色动作，也不改变 RNG 抽取顺序。
 */
import { createAliveComponent } from "../observation/component-presentation";
import { types } from "node:util";
import { z } from "zod";
import { readFaultPlan, type FaultPlan, type FaultStep } from "../../core/domain/fault_plan";
export { readFaultPlan, type FaultPlan, type FaultStep } from "../../core/domain/fault_plan";
const positive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
function inputData(value: unknown): unknown {
  // Decision boundary is equally finite plain data; use the core snapshot helper.
  return readFaultPlanData(value);
}
import { readFaultPlanData } from "../../core/domain/fault_plan";
import { COMPONENT, aliveLifeVersion, aliveLifeDescriptor, type AliveComponent, type World } from "../../core";

const nativePromiseThen = Promise.prototype.then;
const nativePromiseSpecies = Object.getOwnPropertyDescriptor(Promise, Symbol.species)?.get;
export interface FaultDecisionBoundary {
  readonly actorId: number;
  readonly day: number;
  readonly stage: "demon_hunter";
  readonly turn: 1;
  readonly targetId: number;
}
export interface AppliedFault {
  readonly step: FaultStep;
  readonly originalVersion: number;
  readonly replacementVersion: number;
}

/** Explicit offline input; cancellation facts are never consulted to execute a fault. */
export class NightFaultPlan {
  readonly plan: FaultPlan;
  private readonly consumed = new Set<string>();
  private lastDay = 0;
  private failed = false;
  constructor(
    private readonly world: World,
    input: unknown,
  ) {
    this.plan = readFaultPlan(input);
    for (const step of this.plan.steps)
      if (
        !world.hasEntity(step.at.afterDecision.actorId) ||
        !world.hasEntity(step.mutation.playerId)
      )
        throw new Error("fault_plan_player_unknown");
  }

  /** Caller supplies an actual committed choice, before any source in this wave writes Alive. */
  applyBeforeNightSourceFreeze(
    day: number,
    decision: FaultDecisionBoundary | null,
    recordApplied: (fault: AppliedFault) => void,
  ): readonly string[] {
    if (this.failed) throw new Error("fault_plan_failed");
    try {
      return this.apply(day, decision, recordApplied);
    } catch (error) {
      this.failed = true;
      throw error;
    }
  }

  private apply(
    day: number,
    decision: FaultDecisionBoundary | null,
    recordApplied: (fault: AppliedFault) => void,
  ): readonly string[] {
    if (
      typeof recordApplied !== "function" ||
      types.isProxy(recordApplied) ||
      types.isAsyncFunction(recordApplied) ||
      types.isGeneratorFunction(recordApplied)
    )
      throw new Error("fault_plan_recorder_invalid");
    if (!Number.isSafeInteger(day) || day < 1 || day <= this.lastDay)
      throw new Error("fault_plan_boundary_repeated");
    if (this.plan.steps.some((step) => step.at.day < day && !this.consumed.has(step.id)))
      throw new Error("fault_plan_boundary_missed");
    const step = this.plan.steps.find((item) => item.at.day === day);
    if (!step) {
      this.lastDay = day;
      return [];
    }
    if (decision !== null)
      decision = z
        .strictObject({
          actorId: positive,
          day: positive.min(2),
          stage: z.literal("demon_hunter"),
          turn: z.literal(1),
          targetId: positive,
        })
        .parse(inputData(decision));
    if (
      !decision ||
      decision.targetId === decision.actorId ||
      !this.world.hasEntity(decision.targetId) ||
      decision.day !== day ||
      decision.actorId !== step.at.afterDecision.actorId ||
      decision.stage !== step.at.afterDecision.stage ||
      decision.turn !== step.at.afterDecision.turn ||
      ![decision.actorId, decision.targetId].includes(step.mutation.playerId)
    )
      throw new Error("fault_plan_decision_boundary_invalid");
    const original = this.world.getComponent(step.mutation.playerId, COMPONENT.Alive),
      originalVersion = original && aliveLifeVersion(original);
    if (!original || types.isProxy(original) || originalVersion === undefined)
      throw new Error("fault_plan_original_life_invalid");
    const originalDescriptor = aliveLifeDescriptor(original),
      currentDescriptor = Object.getOwnPropertyDescriptor(original, "alive");
    if (
      !originalDescriptor ||
      !currentDescriptor ||
      currentDescriptor.get !== originalDescriptor.get ||
      currentDescriptor.set !== originalDescriptor.set ||
      currentDescriptor.enumerable !== originalDescriptor.enumerable ||
      currentDescriptor.configurable !== originalDescriptor.configurable
    )
      throw new Error("fault_plan_original_life_invalid");
    if (original.alive !== true) throw new Error("fault_plan_original_life_invalid");
    const replacement = createAliveComponent(true, this.world.locale);
    this.world.addComponent(step.mutation.playerId, COMPONENT.Alive, replacement);
    this.consumed.add(step.id);
    this.lastDay = day;
    const result: unknown = recordApplied({
      step,
      originalVersion,
      replacementVersion: aliveLifeVersion(replacement)!,
    });
    if (result !== undefined) {
      if (
        types.isPromise(result) &&
        !types.isProxy(result) &&
        Object.getPrototypeOf(result) === Promise.prototype &&
        !Object.hasOwn(result, "constructor") &&
        Object.getOwnPropertyDescriptor(Promise.prototype, "constructor")?.value === Promise &&
        Object.getOwnPropertyDescriptor(Promise, Symbol.species)?.get === nativePromiseSpecies
      )
        nativePromiseThen.call(result, undefined, () => undefined);
      throw new Error("fault_plan_recorder_not_sync");
    }
    return Object.freeze([step.id]);
  }

  assertConsumed(): void {
    if (this.failed) throw new Error("fault_plan_failed");
    if (this.consumed.size !== this.plan.steps.length) throw new Error("fault_plan_unconsumed");
  }
}

/**
 * 负责按角色运行贡献生成领域工具许可注册表。输入为明确 Catalog，输出为角色与可用工具的原有序登记；公共工具与原贡献去重，不维护第二份角色资料或提示视图，也不授权具体行动租约。
 */
import { RoleRegistry } from "../../../core/domain/registries/role_registry";
import { COMMON_TOOL_SPECS } from "../common/tool_specs";
import { type RoleCatalog } from "./catalog";
import { getDefaultRoleCatalog } from "./role-catalog-assembly";

export function createDefaultRoleRegistry(
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): RoleRegistry {
  const registry = new RoleRegistry();
  const commonTools = COMMON_TOOL_SPECS.map((spec) => spec.name);
  for (const { metadata, runtime: profile } of catalog.allRuntime()) {
    // 在原 register 参数求值点读取角色字段，保留自定义资料 getter 和可变角色标识的原轨迹。
    registry.registerAllowedTools(metadata.role, [
      ...new Set([...commonTools, ...(profile.toolSpecs ?? []).map((spec) => spec.name)]),
    ]);
  }
  return registry;
}

/**
 * 负责猎魔人完整数据槽：原 schema／工具副本、creator、同引用查询、安装及已接受历史写入。
 * 输入为原角色或 authority 的原 state／history／夜时钟；输出保持 live 引用和唯一 historyJson。
 * Node 快照只在原入口拒绝外来 descriptor／Proxy，校验副本不替换运行槽；公共纯结构仍归契约包。
 * 原下一历史先编码，再 push 和更新 JSON；后续 actor 审计、夜选择、请求结算和 stock 写权仍归 authority。
 * 此 owner 不建镜像／第二 WeakMap、不冻结 live 数据或把类型／查询当许可；失败保原部分写入前缀。
 */
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core";
import { DEMON_HUNTER_POLICY, readDemonHunterState as readState, readDemonHuntTool as readTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { DemonHunterState, DemonHuntTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
export { DEMON_HUNTER_POLICY };
export const DEMON_HUNTER_ROLE = "demon_hunter" as const;
export function ownDemonData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function demonSnapshot(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
): unknown {
  return snapshotPlainData(value, seen, depth, arrayLimit, "demon_hunter_data_invalid");
}
export function demonJson(value: unknown): string | null {
  try {
    return JSON.stringify(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function exactDemonData(
  value: unknown,
  keys: readonly string[],
): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
export function freshDemonHunterState(): DemonHunterState {
  return { policy: DEMON_HUNTER_POLICY, history: [] };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  try {
    return readState(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function getDemonHunterState(role: RoleComponent | undefined): DemonHunterState | undefined {
  const s = ownDemonData(ownDemonData(role, "privateState"), "demonHunter");
  // 复制只用于验证；成功后仍返回原 slot，不能让查询生成第二份 live 状态。
  return readDemonHunterState(s) ? (s as DemonHunterState) : undefined;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  try {
    return readTool(demonSnapshot(value));
  } catch {
    return null;
  }
}

/** 唯一 live state／history 和已提交 JSON 留在原 binding 对象，不复制第二份运行库存。 */
export interface DemonHunterStateSlot {
  state: DemonHunterState;
  history: DemonHunterState["history"];
  historyJson: string;
}

/** 初始化仍先求值左侧 privateState，再调用原 creator；没有 schema、授权或新冻结。 */
export function installDemonHunterStateSlot(role: RoleComponent): void {
  (role.privateState as { demonHunter: DemonHunterState }).demonHunter = freshDemonHunterState();
}

/** 原安装字段依次取 state、history，再给空历史 JSON；临时返回对象不成为第二份 live store。 */
export function captureDemonHunterStateSlot(state: DemonHunterState): DemonHunterStateSlot {
  return { state, history: state.history, historyJson: "[]" };
}

/** 数据当前性保持原历史引用优先、已校验历史 JSON 后查；原参与者与 World alias 仍由 authority 核对。 */
export function demonHunterHistoryCurrent(b: DemonHunterStateSlot, state: DemonHunterState): boolean {
  return ownDemonData(b.state, "history") === b.history && demonJson(state.history) === b.historyJson;
}

/**
 * 完整原历史写命令。各 history 与 n.day 均在原表达式处读取；不提前缓存夜时钟。
 * 下一历史 JSON 失败时尚未 push；push 后再写 historyJson，后续抛错保留原历史写入前缀。
 * 返回原冻结 choice；actor.auditPrivateJson、n.choice／turn 和请求结算必须仍由 authority 随后按原序提交。
 */
export function appendDemonHunterChoiceData(
  b: DemonHunterStateSlot,
  n: { readonly day: number },
  targetId: number | null,
): Readonly<DemonHunterState["history"][number]> | null {
  const length = Object.getOwnPropertyDescriptor(b.history, "length");
  if (!length?.writable || !Object.isExtensible(b.history) || (b.history.at(-1)?.day ?? 1) >= n.day)
    return null;
  const choice = Object.freeze({ day: n.day, targetId });
  const nextHistoryJson = demonJson([...b.history, choice]);
  if (nextHistoryJson === null) return null;
  b.history.push(choice);
  b.historyJson = nextHistoryJson;
  return choice;
}
